<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$id=(int)($_GET['id']??0);if(!$id)exit('Invalid event.');if($_SERVER['REQUEST_METHOD']==='POST'){$cid=(int)$_POST['club_id'];$n=trim($_POST['event_name']);$d=trim($_POST['description']);$date=$_POST['event_date'];$time=$_POST['event_time'];$venue=trim($_POST['venue']);$max=(int)$_POST['max_participants'];$deadline=$_POST['registration_deadline'];$s=$conn->prepare('UPDATE events SET club_id=?,event_name=?,description=?,event_date=?,event_time=?,venue=?,max_participants=?,registration_deadline=? WHERE event_id=?');$s->bind_param('isssssisi',$cid,$n,$d,$date,$time,$venue,$max,$deadline,$id);$s->execute();header('Location: manage-events.php');exit;}$s=$conn->prepare('SELECT * FROM events WHERE event_id=?');$s->bind_param('i',$id);$s->execute();$e=$s->get_result()->fetch_assoc();$clubs=$conn->query('SELECT club_id,club_name FROM clubs ORDER BY club_name');?>
<!doctype html><html><head><title>Edit Event</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="form-wrap"><div class="form-box"><h2>Edit Event</h2><form method="post"><label>Club</label><select name="club_id"><?php while($c=$clubs->fetch_assoc()):?><option value="<?=$c['club_id']?>" <?=$c['club_id']==$e['club_id']?'selected':''?>><?=htmlspecialchars($c['club_name'])?></option><?php endwhile;?></select><label>Event Name</label><input name="event_name" value="<?=htmlspecialchars($e['event_name'])?>" required><label>Description</label><textarea name="description" rows="4"><?=htmlspecialchars($e['description'])?></textarea><label>Date</label><input type="date" name="event_date" value="<?=$e['event_date']?>" required><label>Time</label><input type="time" name="event_time" value="<?=$e['event_time']?>" required><label>Venue</label><input name="venue" value="<?=htmlspecialchars($e['venue'])?>" required><label>Max Participants</label><input type="number" name="max_participants" min="1" value="<?=$e['max_participants']?>" required><label>Registration Deadline</label><input type="date" name="registration_deadline" value="<?=$e['registration_deadline']?>" required><br><br><button class="btn full">Update Event</button></form></div></div></body></html>
